use anchor_lang::prelude::*;
use anchor_lang::system_program;
use anchor_spl::token::{self, Mint, MintTo, SetAuthority, Token, TokenAccount, Transfer};
use anchor_spl::token::spl_token::instruction::AuthorityType;
declare_id!("Fg6PaFpoGXkYsidMpWxTWqkZqvFmR6UJA4R9C3bZ9S2");
const DECIMALS:u8=6;const SCALE:u64=1_000_000;const TOTAL:u64=1_000_000_000*SCALE;const LP_TOKENS:u64=200_000_000*SCALE;const TARGET:u64=85_000_000_000;const VIRTUAL_SOL:u64=21_250_000_000;
#[program]pub mod kydos_launchpad{use super::*;pub fn initialize(ctx:Context<Initialize>,name:String,symbol:String,metadata_uri:String)->Result<()>{require!(name.len()<=32,ErrorCode::NameTooLong);require!(symbol.len()<=10,ErrorCode::SymbolTooLong);require!(metadata_uri.len()<=200,ErrorCode::UriTooLong);let curve=&mut ctx.accounts.curve;curve.creator=ctx.accounts.creator.key();curve.mint=ctx.accounts.mint.key();curve.bump=ctx.bumps.curve;curve.decimals=DECIMALS;curve.name=name;curve.symbol=symbol;curve.metadata_uri=metadata_uri;curve.total_supply=TOTAL;curve.token_reserve=TOTAL;curve.real_sol_reserve=0;curve.graduation_target=TARGET;curve.graduated=false;let mint=ctx.accounts.mint.key();let signer:&[&[&[u8]]]=&[&[b"curve",mint.as_ref(),&[curve.bump]]];token::mint_to(CpiContext::new_with_signer(ctx.accounts.token_program.to_account_info(),MintTo{mint:ctx.accounts.mint.to_account_info(),to:ctx.accounts.vault.to_account_info(),authority:curve.to_account_info()},signer),TOTAL)?;for kind in [AuthorityType::MintTokens,AuthorityType::FreezeAccount]{token::set_authority(CpiContext::new_with_signer(ctx.accounts.token_program.to_account_info(),SetAuthority{current_authority:curve.to_account_info(),account_or_mint:ctx.accounts.mint.to_account_info()},signer),kind,None)?;}emit!(LaunchCreated{mint,creator:curve.creator,total_supply:TOTAL});Ok(())}
pub fn buy(ctx:Context<Trade>,sol_in:u64,min_tokens_out:u64)->Result<()>{require!(sol_in>0,ErrorCode::ZeroAmount);let curve=&mut ctx.accounts.curve;let accepted=if curve.graduated{sol_in}else{sol_in.min(TARGET.checked_sub(curve.real_sol_reserve).ok_or(ErrorCode::MathOverflow)?)};require!(accepted>0,ErrorCode::Graduated);let out=if curve.graduated{cp_tokens(curve.real_sol_reserve,curve.token_reserve,accepted)?}else if curve.real_sol_reserve+accepted==TARGET{curve.token_reserve.checked_sub(LP_TOKENS).ok_or(ErrorCode::MathOverflow)?}else{curve_tokens(curve.real_sol_reserve,curve.token_reserve,accepted)?};require!(out>=min_tokens_out&&out>0,ErrorCode::Slippage);system_program::transfer(CpiContext::new(ctx.accounts.system_program.to_account_info(),system_program::Transfer{from:ctx.accounts.trader.to_account_info(),to:curve.to_account_info()}),accepted)?;let mint=curve.mint;let signer:&[&[&[u8]]]=&[&[b"curve",mint.as_ref(),&[curve.bump]]];token::transfer(CpiContext::new_with_signer(ctx.accounts.token_program.to_account_info(),Transfer{from:ctx.accounts.vault.to_account_info(),to:ctx.accounts.trader_tokens.to_account_info(),authority:curve.to_account_info()},signer),out)?;curve.real_sol_reserve=curve.real_sol_reserve.checked_add(accepted).ok_or(ErrorCode::MathOverflow)?;curve.token_reserve=curve.token_reserve.checked_sub(out).ok_or(ErrorCode::MathOverflow)?;if !curve.graduated&&curve.real_sol_reserve==TARGET{curve.graduated=true;emit!(Graduated{mint:curve.mint,sol_reserve:curve.real_sol_reserve,token_reserve:curve.token_reserve});}emit!(TradeExecuted{mint:curve.mint,trader:ctx.accounts.trader.key(),side:0,sol_amount:accepted,token_amount:out,graduated:curve.graduated});Ok(())}
pub fn sell(ctx:Context<Trade>,tokens_in:u64,min_sol_out:u64)->Result<()>{require!(tokens_in>0,ErrorCode::ZeroAmount);let curve=&mut ctx.accounts.curve;let out=if curve.graduated{cp_sol(curve.real_sol_reserve,curve.token_reserve,tokens_in)?}else{curve_sol(curve.real_sol_reserve,curve.token_reserve,tokens_in)?};require!(out>=min_sol_out&&out>0&&out<=curve.real_sol_reserve,ErrorCode::Slippage);token::transfer(CpiContext::new(ctx.accounts.token_program.to_account_info(),Transfer{from:ctx.accounts.trader_tokens.to_account_info(),to:ctx.accounts.vault.to_account_info(),authority:ctx.accounts.trader.to_account_info()}),tokens_in)?;let curve_info=curve.to_account_info();let trader_info=ctx.accounts.trader.to_account_info();**curve_info.try_borrow_mut_lamports()?=curve_info.lamports().checked_sub(out).ok_or(ErrorCode::Liquidity)?;**trader_info.try_borrow_mut_lamports()?=trader_info.lamports().checked_add(out).ok_or(ErrorCode::MathOverflow)?;curve.real_sol_reserve=curve.real_sol_reserve.checked_sub(out).ok_or(ErrorCode::MathOverflow)?;curve.token_reserve=curve.token_reserve.checked_add(tokens_in).ok_or(ErrorCode::MathOverflow)?;emit!(TradeExecuted{mint:curve.mint,trader:ctx.accounts.trader.key(),side:1,sol_amount:out,token_amount:tokens_in,graduated:curve.graduated});Ok(())}}
fn curve_tokens(sol:u64,tokens:u64,input:u64)->Result<u64>{let x=VIRTUAL_SOL as u128+sol as u128;let next=x.checked_mul(tokens as u128).ok_or(ErrorCode::MathOverflow)?/x.checked_add(input as u128).ok_or(ErrorCode::MathOverflow)?;u64::try_from(tokens as u128-next).map_err(|_|error!(ErrorCode::MathOverflow))}fn curve_sol(sol:u64,tokens:u64,input:u64)->Result<u64>{let x=VIRTUAL_SOL as u128+sol as u128;let next=x.checked_mul(tokens as u128).ok_or(ErrorCode::MathOverflow)?/(tokens as u128+input as u128);u64::try_from(x-next).map_err(|_|error!(ErrorCode::MathOverflow))}fn cp_tokens(sol:u64,tokens:u64,input:u64)->Result<u64>{let next=(sol as u128).checked_mul(tokens as u128).ok_or(ErrorCode::MathOverflow)?/(sol as u128+input as u128);u64::try_from(tokens as u128-next).map_err(|_|error!(ErrorCode::MathOverflow))}fn cp_sol(sol:u64,tokens:u64,input:u64)->Result<u64>{let next=(sol as u128).checked_mul(tokens as u128).ok_or(ErrorCode::MathOverflow)?/(tokens as u128+input as u128);u64::try_from(sol as u128-next).map_err(|_|error!(ErrorCode::MathOverflow))}
#[derive(Accounts)]pub struct Initialize<'info>{#[account(mut)]pub creator:Signer<'info>,#[account(init,payer=creator,mint::decimals=DECIMALS,mint::authority=curve,mint::freeze_authority=curve)]pub mint:Account<'info,Mint>,#[account(init,payer=creator,seeds=[b"curve",mint.key().as_ref()],bump,space=Curve::SPACE)]pub curve:Account<'info,Curve>,#[account(init,payer=creator,seeds=[b"vault",mint.key().as_ref()],bump,token::mint=mint,token::authority=curve)]pub vault:Account<'info,TokenAccount>,pub token_program:Program<'info,Token>,pub system_program:Program<'info,System>,pub rent:Sysvar<'info,Rent>}
#[derive(Accounts)]pub struct Trade<'info>{#[account(mut)]pub trader:Signer<'info>,#[account(mut,seeds=[b"curve",mint.key().as_ref()],bump=curve.bump,has_one=mint)]pub curve:Account<'info,Curve>,pub mint:Account<'info,Mint>,#[account(mut,seeds=[b"vault",mint.key().as_ref()],bump,token::mint=mint,token::authority=curve)]pub vault:Account<'info,TokenAccount>,#[account(mut,token::mint=mint,token::authority=trader)]pub trader_tokens:Account<'info,TokenAccount>,pub token_program:Program<'info,Token>,pub system_program:Program<'info,System>}
#[account]pub struct Curve{pub creator:Pubkey,pub mint:Pubkey,pub bump:u8,pub decimals:u8,pub name:String,pub symbol:String,pub metadata_uri:String,pub total_supply:u64,pub token_reserve:u64,pub real_sol_reserve:u64,pub graduation_target:u64,pub graduated:bool}impl Curve{pub const SPACE:usize=8+32+32+1+1+4+32+4+10+4+200+8*4+1;}#[event]pub struct LaunchCreated{pub mint:Pubkey,pub creator:Pubkey,pub total_supply:u64}#[event]pub struct TradeExecuted{pub mint:Pubkey,pub trader:Pubkey,pub side:u8,pub sol_amount:u64,pub token_amount:u64,pub graduated:bool}#[event]pub struct Graduated{pub mint:Pubkey,pub sol_reserve:u64,pub token_reserve:u64}#[error_code]pub enum ErrorCode{#[msg("Amount must be positive")]ZeroAmount,#[msg("Slippage exceeded")]Slippage,#[msg("Arithmetic overflow")]MathOverflow,#[msg("Curve graduated")]Graduated,#[msg("Insufficient liquidity")]Liquidity,#[msg("Name too long")]NameTooLong,#[msg("Symbol too long")]SymbolTooLong,#[msg("URI too long")]UriTooLong}
